    color: '#ffffff',
    border: 'none',
    padding: '6px 12px',
    borderRadius: '6px',
    fontSize: '0.78rem',
    fontWeight: '600',
    cursor: 'pointer'
  },
  historyCard: {
    backgroundColor: '#18181b',
    padding: '12px',
    borderRadius: '8px',
    border: '1px solid #3f3f46'
  },
  gatewayGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
    gap: '16px'
  },
  gatewayCard: {
    backgroundColor: '#18181b',
    padding: '18px',
    borderRadius: '12px',
    border: '1px solid #3f3f46',
    display: 'flex',
    flexDirection: 'column',
    gap: '12px'
  },
  connectedBadge: {
    backgroundColor: '#15803d',
    color: '#ffffff',
    fontSize: '0.7rem',
    padding: '2px 8px',
    borderRadius: '10px',
    fontWeight: '700'
  },
  keyRow: {
    display: 'flex',
    alignItems: 'center',
    gap: '6px'
  },
  modalOverlay: {
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(0, 0, 0, 0.75)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 1000
  },
  modalContent: {
    backgroundColor: '#27272a',
    border: '1px solid #3f3f46',
    borderRadius: '16px',
    padding: '24px',
    width: '100%'
  },
  modalHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    marginBottom: '20px'
  },
  closeBtn: {
    background: 'none',
    border: 'none',
    color: '#a1a1aa',
    cursor: 'pointer'
  },
  modalForm: {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px'
  },
  fieldGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '6px'
  },
  modalLabel: {
    fontSize: '0.8rem',
    color: '#a1a1aa',
    fontWeight: '600',
    display: 'flex',
    alignItems: 'center',
    gap: '6px'
  },
  modalInput: {
    padding: '10px 14px',
    borderRadius: '8px',
    border: '1px solid #3f3f46',
    backgroundColor: '#18181b',
    color: '#ffffff',
    outline: 'none'
  },
  modalSelect: {
    padding: '10px 14px',
    borderRadius: '8px',
    border: '1px solid #3f3f46',
    backgroundColor: '#18181b',
    color: '#ffffff',
    outline: 'none',
    cursor: 'pointer'
  },
  formRow: {
    display: 'flex',
    gap: '12px',
    flexWrap: 'wrap'
  },
  uploadBox: {
    backgroundColor: '#18181b',
    border: '1px dashed #3f3f46',
    borderRadius: '8px',
    padding: '12px',
    display: 'flex',
    flexDirection: 'column',
    gap: '10px'
  },
  uploadLabelBtn: {
    alignSelf: 'flex-start',
    display: 'inline-flex',
    alignItems: 'center',
    gap: '6px',
    backgroundColor: '#3f3f46',
    color: '#ffffff',
    padding: '6px 12px',
    borderRadius: '6px',
    fontSize: '0.8rem',
    cursor: 'pointer'
  },
  imagePreviewRow: {
    display: 'flex',
    gap: '8px',
    flexWrap: 'wrap'
  },
  imgBadgeWrapper: {
    position: 'relative'
  },
  previewThumb: {
    width: '50px',
    height: '50px',
    borderRadius: '6px',
    objectFit: 'cover',
    border: '1px solid #3f3f46'
  },
  removeImgBtn: {
    position: 'absolute',
    top: '-4px',
    right: '-4px',
    backgroundColor: '#ef4444',
    color: '#fff',
    border: 'none',
    borderRadius: '50%',
    width: '16px',
    height: '16px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    cursor: 'pointer'
  },
  modalActions: {
    display: 'flex',
    justifyContent: 'flex-end',
    gap: '12px',
    marginTop: '12px'
  },
  cancelBtn: {
    padding: '10px 16px',
    borderRadius: '8px',
    border: 'none',
    backgroundColor: '#3f3f46',
    color: '#ffffff',
    fontWeight: '600',
    cursor: 'pointer'
  },
  submitModalBtn: {
    padding: '10px 18px',
    borderRadius: '8px',
    border: 'none',
    backgroundColor: '#ea580c',
    color: '#ffffff',
    fontWeight: '600',
    cursor: 'pointer'
  }
};
var _c;
$RefreshReg$(_c, "Admin");

sourcesContent:
import React, { useState, useEffect } from 'react';
import { 
  Bus, 
  PlusCircle, 
  Users, 
  Ticket, 
  TrendingUp, 
  User as UserIcon, 
  CreditCard,
  Trash2,
  X,
  Shield,
  Key,
  DollarSign,
  Lock,
  Phone,
  Mail,
  UserCheck,
  History,
  Image as ImageIcon,
  Clock,
  Hash,
  ArrowRight,
  Info,
  ShieldCheck,
  Sparkles,
  Edit3,
  Download,
  Calendar,
  CheckCircle,
  AlertCircle
} from 'lucide-react';

const BANGLADESH_DISTRICTS = [
  'Bagerhat', 'Bandarban', 'Barguna', 'Barishal', 'Bhola', 'Bogra', 'Brahmanbaria', 'Chandpur', 
  'Chittagong', 'Chuadanga', 'Comilla', 'Cox\'s Bazar', 'Dhaka', 'Dinajpur', 'Faridpur', 'Feni', 
  'Gaibandha', 'Gazipur', 'Gopalganj', 'Habiganj', 'Jamalpur', 'Jessore', 'Jhalokati', 'Jhenaidah', 
  'Joypurhat', 'Khagrachhari', 'Khulna', 'Kishoreganj', 'Kurigram', 'Kushtia', 'Lakshmipur', 'Lalmonirhat', 
  'Madaripur', 'Magura', 'Manikganj', 'Meherpur', 'Moulvibazar', 'Munshiganj', 'Mymensingh', 'Naogaon', 
  'Narail', 'Narayanganj', 'Narsingdi', 'Natore', 'Nawabganj', 'Netrokona', 'Nilphamari', 'Noakhali', 
  'Pabna', 'Panchagarh', 'Patuakhali', 'Pirojpur', 'Rajbari', 'Rajshahi', 'Rangamati', 'Rangpur', 
  'Satkhira', 'Shariatpur', 'Sherpur', 'Sirajganj', 'Sunamganj', 'Sylhet', 'Tangail', 'Thakurgaon'
];

const BUS_TYPES = [
  'Sleeper Class AC Coach (28 berths)',
  'Business / VIP Class AC Coach (28 seats)',
  'Premium Recliner AC Coach (32 seats)',
  'Standard Executive AC Coach (36 seats)',
  'BRTC Double-Decker Highway Bus (40 seats)',
  'Standard Non-AC Highway Coach (52 seats)',
  'Economy / High-Density Non-AC Bus (55 seats)',
  'Mini / Hilly Route Regional Coach (30 seats)'
];

const SEAT_OPTIONS = [20, 24, 28, 32, 36, 40, 52];

const INITIAL_FORM_STATE = {
  name: '',
  busNumber: '',
  from: '',
  to: '',
  busType: '',
  fare: '',
  seats: 36,
  arrivalTime: '',
  departureTime: '',
  estimatedHours: '',
  images: []
};

export default function Admin({ user = {}, activeTab = 'home' }) {
  const [buses, setBuses] = useState(() => {
    const savedBuses = localStorage.getItem('app_buses');
    return savedBuses ? JSON.parse(savedBuses) : [
      { 
        id: 101, 
        name: 'Green Line Paribahan', 
        busNumber: 'GL-501',
        from: 'Dhaka',
        to: 'Cox\'s Bazar',
        route: 'Dhaka to Cox\'s Bazar', 
        fare: '1500 BDT', 
        seats: 28,
        bookedSeats: ['A1', 'A2', 'B3'],
        busType: 'Sleeper Class AC Coach (28 berths)',
        arrivalTime: '21:30',
        departureTime: '22:00',
        estimatedHours: '10 hrs',
        images: []
      },
      { 
        id: 102, 
        name: 'Ena Transport', 
        busNumber: 'ENA-302',
        from: 'Dhaka',
        to: 'Sylhet',
        route: 'Dhaka to Sylhet', 
        fare: '800 BDT', 
        seats: 36,
        bookedSeats: ['A3', 'C1', 'C2', 'D4'],
        busType: 'Standard Executive AC Coach (36 seats)',
        arrivalTime: '07:00',
        departureTime: '07:30',
        estimatedHours: '6 hrs',
        images: []
      }
    ];
  });

  const [registeredUsers, setRegisteredUsers] = useState([]);
  const [ticketSales, setTicketSales] = useState(() => {
    const savedTickets = localStorage.getItem('app_tickets');
    return savedTickets ? JSON.parse(savedTickets) : [];
  });

  const [selectedUserHistory, setSelectedUserHistory] = useState(null);
  const [selectedBusDetails, setSelectedBusDetails] = useState(null);
  const [activeImageIndex, setActiveImageIndex] = useState(0);

  const [profileImage, setProfileImage] = useState(() => {
    return localStorage.getItem(`avatar_${user?.emailOrPhone || 'admin'}`) || null;
  });

  useEffect(() => {
    const syncData = () => {
      const loadedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
      const loadedTickets = JSON.parse(localStorage.getItem('app_tickets') || '[]');
      setRegisteredUsers(loadedUsers);
      setTicketSales(loadedTickets);
    };

    syncData();
    window.addEventListener('storage', syncData);
    return () => window.removeEventListener('storage', syncData);
  }, [activeTab]);

  useEffect(() => {
    localStorage.setItem('app_buses', JSON.stringify(buses));
  }, [buses]);

  const totalTicketsSold = ticketSales.length;
  const totalRevenue = ticketSales.reduce((acc, item) => {
    const price = typeof item.fare === 'number' 
      ? item.fare 
      : parseInt(String(item.fare || '0').replace(/[^0-9]/g, ''), 10) || 0;
    return acc + price;
  }, 0);

  const [passwordData, setPasswordData] = useState({ current: '', new: '', confirm: '' });
  const [pwdMsg, setPwdMsg] = useState({ type: '', text: '' });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newBus, setNewBus] = useState(INITIAL_FORM_STATE);

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setNewBus(INITIAL_FORM_STATE);
  };

  const handleBusImagesUpload = (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;

    const filePromises = files.map((file) => {
      return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.readAsDataURL(file);
      });
    });

    Promise.all(filePromises).then((base64Images) => {
      setNewBus((prev) => ({
        ...prev,
        images: [...prev.images, ...base64Images]
      }));
    });
  };

  const handleRemoveImage = (indexToRemove) => {
    setNewBus((prev) => ({
      ...prev,
      images: prev.images.filter((_, idx) => idx !== indexToRemove)
    }));
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Image = reader.result;
        setProfileImage(base64Image);
        localStorage.setItem(`avatar_${user?.emailOrPhone || 'admin'}`, base64Image);
      };
      reader.readAsDataURL(file);
    }
  };

  const handlePasswordSubmit = (e) => {
    e.preventDefault();
    if (!passwordData.current || !passwordData.new || !passwordData.confirm) {
      setPwdMsg({ type: 'error', text: 'Please fill in all password fields.' });
      return;
    }
    if (passwordData.new !== passwordData.confirm) {
      setPwdMsg({ type: 'error', text: 'New passwords do not match!' });
      return;
    }
    if (passwordData.new.length < 6) {
      setPwdMsg({ type: 'error', text: 'Password must be at least 6 characters.' });
      return;
    }

    setPwdMsg({ type: 'success', text: 'Password updated successfully!' });
    setPasswordData({ current: '', new: '', confirm: '' });
  };

  const handleDeleteBus = (e, id) => {
    e.stopPropagation();
    setBuses(buses.filter((bus) => bus.id !== id));
  };

  const handleAddBusSubmit = (e) => {
    e.preventDefault();
    if (!newBus.name || !newBus.busNumber || !newBus.fare || !newBus.from || !newBus.to || !newBus.busType) {
      alert('Please fill out all required route details!');
      return;
    }

    const createdBus = {
      id: Math.floor(100 + Math.random() * 900),
      name: newBus.name,
      busNumber: newBus.busNumber,
      from: newBus.from,
      to: newBus.to,
      route: `${newBus.from} to ${newBus.to}`,
      fare: newBus.fare.includes('BDT') ? newBus.fare : `${newBus.fare} BDT`,
      seats: Number(newBus.seats) || 36,
      bookedSeats: [],
      busType: newBus.busType,
      arrivalTime: newBus.arrivalTime || 'N/A',
      departureTime: newBus.departureTime || 'N/A',
      estimatedHours: newBus.estimatedHours ? `${newBus.estimatedHours} hrs` : 'N/A',
      images: newBus.images
    };

    setBuses([...buses, createdBus]);
    handleCloseModal();
  };

  return (
    <div style={styles.container}>
      {/* 1. HOME TAB - UNCHANGED */}
      {activeTab === 'home' && (
        <>
          <div style={styles.headerRow}>
            <div>
              <h2 style={styles.title}>Admin Panel ({user?.name || 'Administrator'})</h2>
              <p style={styles.subText}>System Overview & Fleet Management</p>
            </div>
            <button style={styles.addBtn} onClick={() => { setNewBus(INITIAL_FORM_STATE); setIsModalOpen(true); }}>
              <PlusCircle size={18} /> Add Bus Route
            </button>
          </div>

          {/* Key Metrics Grid */}
          <div style={styles.statsGrid}>
            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Bus size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>{buses.length} Active Buses</h3>
                <span style={styles.statLabel}>Operational Fleets</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Users size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>{registeredUsers.length} Real Users</h3>
                <span style={styles.statLabel}>Registered Accounts</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Ticket size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>{totalTicketsSold} Tickets</h3>
                <span style={styles.statLabel}>Sold Today</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><TrendingUp size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>৳ {totalRevenue.toLocaleString()}</h3>
                <span style={styles.statLabel}>Total Revenue</span>
              </div>
            </div>
          </div>

          {/* ACTIVE ROUTE BOXES */}
          <div style={styles.card}>
            <div style={styles.tableHeader}>
              <h3 style={styles.cardTitle}>Active Bus Routes</h3>
              <span style={styles.countBadge}>{buses.length} Routes Configured</span>
            </div>

            {buses.length === 0 ? (
              <div style={styles.emptyBox}>
                <Bus size={36} color="#71717a" />
                <p>No bus routes added yet. Click "+ Add Bus Route" above to create one.</p>
              </div>
            ) : (
              <div style={styles.routeGrid}>
                {buses.map((bus) => (
                  <div 
                    key={bus.id} 
                    style={styles.routeBox} 
                    onClick={() => { setSelectedBusDetails(bus); setActiveImageIndex(0); }}
                  >
                    <div style={styles.boxImageArea}>
                      {bus.images && bus.images.length > 0 ? (
                        <img src={bus.images[0]} alt={bus.name} style={styles.boxImg} />
                      ) : (
                        <div style={styles.boxImgPlaceholder}>
                          <Bus size={40} color="#52525b" />
                          <span>No Image Attached</span>
                        </div>
                      )}
                      <span style={styles.boxIdTag}>#{bus.id}</span>
                      <button 
                        style={styles.boxDeleteBtn} 
                        title="Delete Route" 
                        onClick={(e) => handleDeleteBus(e, bus.id)}
                      >
                        <Trash2 size={15} />
                      </button>
                    </div>

                    <div style={styles.boxBody}>
                      <div style={styles.operatorName}>{bus.name}</div>
                      
                      <div style={styles.boxRouteTitle}>
                        {bus.route || `${bus.from} to ${bus.to}`}
                      </div>

                      <div style={styles.seatSummaryRow}>
                        <span style={styles.seatSummaryText}>
                          Capacity: <strong>{bus.seats} Seats</strong>
                        </span>
                        <span style={styles.bookedCountBadge}>
                          {(bus.bookedSeats || []).length} Booked
                        </span>
                      </div>

                      <div style={styles.boxFooter}>
                        <div>
                          <span style={styles.fareLabel}>Ticket Price</span>
                          <div style={styles.boxFare}>{bus.fare}</div>
                        </div>
                        <span style={styles.viewDetailsHint}>
                          View Layout <ArrowRight size={14} />
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      )}

      {/* 2. PROFILE TAB (PERFECTED & BEAUTIFIED) */}
      {activeTab === 'profile' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
          
          {/* Main Administrator Profile Card */}
          <div style={styles.card}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px', borderBottom: '1px solid #3f3f46', paddingBottom: '18px', marginBottom: '24px' }}>
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <UserIcon size={24} color="#ea580c" />
                  <h2 style={styles.cardTitle}>Administrator Profile</h2>
                </div>
                <p style={{ margin: '4px 0 0 0', color: '#a1a1aa', fontSize: '0.85rem' }}>
                  Manage system administrative details and system privileges
                </p>
              </div>

              <div style={{ display: 'flex', gap: '10px' }}>
                <span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', backgroundColor: 'rgba(34, 197, 94, 0.15)', color: '#22c55e', border: '1px solid rgba(34, 197, 94, 0.3)', padding: '6px 12px', borderRadius: '20px', fontSize: '0.78rem', fontWeight: '600' }}>
                  <CheckCircle size={14} /> System Active
                </span>
                <button style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', backgroundColor: '#3f3f46', color: '#f4f4f5', border: 'none', padding: '6px 14px', borderRadius: '8px', fontSize: '0.8rem', fontWeight: '600', cursor: 'pointer' }}>
                  <Edit3 size={14} /> Edit Info
                </button>
              </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'auto 1fr', gap: '32px', alignItems: 'center' }}>
              {/* Avatar Upload Container */}
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px' }}>
                <div style={styles.avatarContainer}>
                  <div style={styles.avatarCircle}>
                    {profileImage ? (
                      <img src={profileImage} alt="Profile" style={styles.avatarImg} />
                    ) : (
                      <UserIcon size={52} color="#a1a1aa" />
                    )}
                  </div>
                  <label htmlFor="photo-upload" style={styles.cameraBtn} title="Upload Profile Picture">
                    <ImageIcon size={14} color="#ffffff" />
                    <input 
                      id="photo-upload" 
                      type="file" 
                      accept="image/*" 
                      onChange={handleImageChange} 
                      style={{ display: 'none' }} 
                    />
                  </label>
                </div>
                <span style={{ fontSize: '0.75rem', color: '#a1a1aa', textAlign: 'center' }}>
                  Allowed JPG, PNG (Max 2MB)
                </span>
              </div>

              {/* Enhanced Info Grid */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '16px' }}>
                <div style={{ backgroundColor: '#18181b', padding: '14px 18px', borderRadius: '12px', border: '1px solid #3f3f46' }}>
                  <span style={{ fontSize: '0.75rem', color: '#a1a1aa', display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '4px' }}>
                    <UserIcon size={14} color="#ea580c" /> Full Name
                  </span>
                  <div style={{ color: '#f4f4f5', fontWeight: '700', fontSize: '1rem' }}>
                    {user?.name || 'Super Administrator'}
                  </div>
                </div>

                <div style={{ backgroundColor: '#18181b', padding: '14px 18px', borderRadius: '12px', border: '1px solid #3f3f46' }}>
                  <span style={{ fontSize: '0.75rem', color: '#a1a1aa', display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '4px' }}>
                    <Mail size={14} color="#ea580c" /> Email Address
                  </span>
                  <div style={{ color: '#f4f4f5', fontWeight: '600', fontSize: '0.95rem' }}>
                    {user?.emailOrPhone || 'admin@onlinebus.bd'}
                  </div>
                </div>

                <div style={{ backgroundColor: '#18181b', padding: '14px 18px', borderRadius: '12px', border: '1px solid #3f3f46' }}>
                  <span style={{ fontSize: '0.75rem', color: '#a1a1aa', display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '4px' }}>
                    <Phone size={14} color="#ea580c" /> Phone Contact
                  </span>
                  <div style={{ color: '#f4f4f5', fontWeight: '600', fontSize: '0.95rem' }}>
                    {user?.phone || '+880 1700-000000'}
                  </div>
                </div>

                <div style={{ backgroundColor: '#18181b', padding: '14px 18px', borderRadius: '12px', border: '1px solid #3f3f46' }}>
                  <span style={{ fontSize: '0.75rem', color: '#a1a1aa', display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '4px' }}>
                    <Shield size={14} color="#ea580c" /> Assigned Authority
                  </span>
                  <div>
                    <span style={styles.roleBadge}>Super Admin Portal</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Registered Users Audit Section */}
          <div style={styles.card}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', flexWrap: 'wrap', gap: '12px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <UserCheck size={22} color="#ea580c" />
                <div>
                  <h3 style={styles.cardTitle}>Registered Passengers</h3>
                  <span style={{ fontSize: '0.8rem', color: '#a1a1aa' }}>
                    Live user database synchronized across system terminals
                  </span>
                </div>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <span style={styles.countBadge}>{registeredUsers.length} Active Accounts</span>
                <button style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', backgroundColor: '#18181b', color: '#a1a1aa', border: '1px solid #3f3f46', padding: '6px 12px', borderRadius: '8px', fontSize: '0.78rem', cursor: 'pointer' }}>
                  <Download size={14} /> Export CSV
                </button>
              </div>
            </div>

            {registeredUsers.length === 0 ? (
              <div style={styles.emptyBox}>
                <Users size={36} color="#71717a" />
                <p>No registered passengers recorded in the database.</p>
              </div>
            ) : (
              <div style={{ overflowX: 'auto', borderRadius: '10px', border: '1px solid #3f3f46' }}>
                <table style={styles.table}>
                  <thead>
                    <tr style={{ backgroundColor: '#18181b' }}>
