                              <div
                                key={seatId}
                                style={{
                                  ...styles.compactSeat,
                                  backgroundColor: isBooked(seatId) ? '#6b7280' : '#22c55e',
                                }}
                                title={isBooked(seatId) ? `Seat ${seatId}: Booked` : `Seat ${seatId}: Available`}
                              >
                                {seatId}
                              </div>
                            ))}
                          </div>
                        </div>
